ITEMS.append({
 "id": "l101-ann-elegxos-orasis", "title": "Δωρεάν έλεγχος όρασης στο δημαρχείο", "title_en": "Free eye tests at the town hall", "type": "announcement", "level": "B2",
 "context_el": "Ακούτε μια ανακοίνωση του δήμου σε έναν τοπικό ραδιοφωνικό σταθμό.",
 "script": [
  L("Εκφωνητής", "m", "Ο δήμος ανακοινώνει ότι την ερχόμενη εβδομάδα, από τη Δευτέρα έως την Παρασκευή, θα πραγματοποιείται δωρεάν έλεγχος όρασης στην αίθουσα εκδηλώσεων του δημαρχείου. Τον έλεγχο θα κάνουν οφθαλμίατροι του νοσοκομείου, σε συνεργασία με τον σύλλογο των οπτικών της πόλης.", "The municipality announces that next week, from Monday to Friday, free eye tests will take place in the events hall of the town hall. The tests will be carried out by ophthalmologists from the hospital, in cooperation with the town's Association of Opticians."),
  L("Εκφωνητής", "m", "Το πρόγραμμα απευθύνεται κυρίως σε παιδιά δημοτικού και σε άτομα άνω των εξήντα πέντε ετών, ηλικίες στις οποίες τα προβλήματα όρασης συχνά δεν γίνονται αντιληπτά εγκαίρως. Για τα παιδιά απαιτείται η παρουσία ενός γονέα ή κηδεμόνα. Ο έλεγχος διαρκεί περίπου δεκαπέντε λεπτά.", "The programme is aimed mainly at primary school children and people over sixty-five, ages at which vision problems are often not noticed in time. For children, the presence of a parent or guardian is required. The test lasts about fifteen minutes."),
  L("Εκφωνητής", "m", "Λόγω του μεγάλου ενδιαφέροντος, η εξέταση γίνεται μόνο με ραντεβού, το οποίο μπορείτε να κλείσετε στο τηλέφωνο του δήμου. Παρακαλούνται όσοι φορούν ήδη γυαλιά ή φακούς επαφής να τα φέρουν μαζί τους.", "Because of the great interest, the examination is by appointment only, which you can book on the municipality's phone line. Those who already wear glasses or contact lenses are asked to bring them along."),
 ],
 "questions": [
  Q("Ποιοι θα κάνουν τον έλεγχο;", ["Φοιτητές ιατρικής", "Οφθαλμίατροι του νοσοκομείου", "Υπάλληλοι του δήμου", "Δάσκαλοι"], 1, "Τον έλεγχο θα κάνουν οφθαλμίατροι του νοσοκομείου"),
  Q("Σε ποιους απευθύνεται κυρίως το πρόγραμμα;", ["Σε οδηγούς", "Σε φοιτητές", "Σε παιδιά δημοτικού και σε άτομα άνω των εξήντα πέντε", "Σε όλους τους εργαζόμενους"], 2, "απευθύνεται κυρίως σε παιδιά δημοτικού και σε άτομα άνω των εξήντα πέντε ετών"),
  Q("Τι πρέπει να φέρουν όσοι φορούν ήδη γυαλιά;", ["Τα γυαλιά ή τους φακούς τους", "Τη συνταγή του γιατρού", "Μια φωτογραφία", "Την αστυνομική τους ταυτότητα"], 0, "να τα φέρουν μαζί τους"),
 ],
 "gloss": {"όρασης": "όραση — eyesight, vision", "πραγματοποιείται": "πραγματοποιούμαι — to take place", "εκδηλώσεων": "εκδήλωση — event", "οφθαλμίατροι": "οφθαλμίατρος — ophthalmologist", "οπτικών": "οπτικός — optician", "απευθύνεται": "απευθύνομαι — to be aimed at", "αντιληπτά": "αντιληπτός — noticeable", "εγκαίρως": "εγκαίρως — in time", "κηδεμόνα": "κηδεμόνας — guardian", "φακούς": "φακός επαφής — contact lens"}
})
ITEMS.append({
 "id": "l101-vm-mastoras-plakakia", "title": "Μήνυμα από τον μάστορα για τα πλακάκια", "title_en": "A message from the tiler", "type": "voicemail", "level": "B2",
 "context_el": "Αυτόν τον καιρό ανακαινίζετε το μπάνιο σας. Ακούτε ένα μήνυμα από τον τεχνίτη στον τηλεφωνητή σας.",
 "script": [
  L("Τεχνίτης", "m", "Καλημέρα σας, ο Σταύρος είμαι, για το μπάνιο. Σας πήρα να σας πω ότι ξήλωσα τα παλιά πλακάκια, και πίσω από τον τοίχο της μπανιέρας βρήκα υγρασία. Δεν είναι κάτι τραγικό, αλλά ένας σωλήνας στάζει μάλλον εδώ και καιρό, και πρέπει να τον αλλάξει υδραυλικός πριν βάλουμε τα καινούργια.", "Good morning, it's Stavros, about the bathroom. I'm calling to tell you that I removed the old tiles, and behind the bathtub wall I found damp. It's nothing tragic, but a pipe has probably been dripping for a while, and a plumber has to replace it before we put up the new ones."),
  L("Τεχνίτης", "m", "Έχω έναν υδραυλικό που συνεργάζομαι, μπορεί να έρθει αύριο το πρωί. Αυτό σημαίνει ότι θα καθυστερήσουμε δύο μέρες, γιατί ο τοίχος πρέπει να στεγνώσει καλά. Αν βάλουμε πλακάκια πάνω σε βρεγμένο τοίχο, σε έναν χρόνο θα ξεκολλήσουν.", "I have a plumber I work with, he can come tomorrow morning. That means we'll be delayed by two days, because the wall has to dry properly. If we put tiles on a wet wall, in a year they'll come off."),
  L("Τεχνίτης", "m", "Και κάτι ακόμα: από τα πλακάκια που διαλέξατε, το κατάστημα μου είπε ότι το γκρι έχει τελειώσει και θα έρθει σε τρεις εβδομάδες. Υπάρχει ένα πολύ παρόμοιο, λίγο πιο ανοιχτό. Περάστε, αν μπορείτε, από το κατάστημα να το δείτε, και πείτε μου τι θέλετε να κάνουμε. Ευχαριστώ!", "And one more thing: of the tiles you chose, the shop told me the grey one has run out and will arrive in three weeks. There is a very similar one, a little lighter. If you can, drop by the shop to see it, and tell me what you want us to do. Thanks!"),
 ],
 "questions": [
  Q("Τι βρήκε ο τεχνίτης πίσω από τον τοίχο της μπανιέρας;", ["Παλιά καλώδια", "Υγρασία από έναν σωλήνα που στάζει", "Μια ρωγμή", "Μούχλα στα πλακάκια"], 1, "βρήκα υγρασία"),
  Q("Γιατί θα καθυστερήσουν δύο μέρες;", ["Γιατί ο υδραυλικός είναι άρρωστος", "Γιατί ο τοίχος πρέπει να στεγνώσει καλά", "Γιατί είναι αργία", "Γιατί λείπουν εργαλεία"], 1, "ο τοίχος πρέπει να στεγνώσει καλά"),
  Q("Τι πρόβλημα υπάρχει με τα γκρι πλακάκια;", ["Είναι πιο ακριβά", "Έχουν σπάσει", "Έχουν τελειώσει και θα έρθουν σε τρεις εβδομάδες", "Δεν ταιριάζουν με την μπανιέρα"], 2, "το γκρι έχει τελειώσει και θα έρθει σε τρεις εβδομάδες"),
 ],
 "gloss": {"ανακαινίζετε": "ανακαινίζω — to renovate", "τεχνίτη": "τεχνίτης — craftsman, workman", "ξήλωσα": "ξηλώνω — to rip out, remove", "πλακάκια": "πλακάκι — tile", "υγρασία": "υγρασία — damp, moisture", "σωλήνας": "σωλήνας — pipe", "στάζει": "στάζω — to drip", "υδραυλικός": "υδραυλικός — plumber", "βρεγμένο": "βρεγμένος — wet", "ξεκολλήσουν": "ξεκολλάω — to come unstuck", "παρόμοιο": "παρόμοιος — similar"}
})
ITEMS.append({
 "id": "l101-dia-paidotopos", "title": "Πάρτι γενεθλίων σε παιδότοπο", "title_en": "A birthday party at a children's play centre", "type": "dialogue", "level": "B2",
 "context_el": "Μια μητέρα τηλεφωνεί σε έναν παιδότοπο για να κλείσει το πάρτι γενεθλίων του γιου της.",
 "script": [
  L("Μητέρα", "f", "Καλησπέρα. Θα ήθελα να ρωτήσω για πάρτι γενεθλίων. Ο γιος μου κλείνει τα έξι στις είκοσι Μαρτίου, και σκεφτόμασταν να το κάνουμε σε εσάς το Σάββατο μετά.", "Good afternoon. I'd like to ask about birthday parties. My son turns six on the twentieth of March, and we were thinking of having it at your place on the Saturday after."),
  L("Υπάλληλος", "m", "Μάλιστα. Το Σάββατο είκοσι δύο έχουμε ελεύθερο μόνο το απογευματινό τρίωρο, από τις πέντε ως τις οχτώ. Το πρωινό έχει κλειστεί. Πόσα παιδιά περίπου θα έρθουν;", "Right. On Saturday the twenty-second we only have the afternoon three-hour slot free, from five to eight. The morning is booked. About how many children will come?"),
  L("Μητέρα", "f", "Γύρω στα είκοσι, όλη η τάξη του. Και φυσικά μερικοί γονείς.", "Around twenty, his whole class. And of course some parents."),
  L("Υπάλληλος", "m", "Το βασικό πακέτο είναι για είκοσι παιδιά και περιλαμβάνει δύο εμψυχωτές, παιχνίδια και ένα απλό μενού για τα παιδιά: τοστ, χυμούς και ποπ κορν. Για τους γονείς υπάρχει καφές. Την τούρτα μπορείτε να τη φέρετε εσείς, ή να την παραγγείλουμε εμείς από το ζαχαροπλαστείο απέναντι.", "The basic package is for twenty children and includes two entertainers, games and a simple menu for the children: toasted sandwiches, juices and popcorn. For the parents there is coffee. You can bring the cake yourselves, or we can order it from the patisserie opposite."),
  L("Μητέρα", "f", "Ένα από τα παιδιά έχει σοβαρή αλλεργία στους ξηρούς καρπούς. Είναι πρόβλημα;", "One of the children has a serious nut allergy. Is that a problem?"),
  L("Υπάλληλος", "m", "Καθόλου, αρκεί να μας το πείτε από πριν. Θα ετοιμάσουμε ξεχωριστό φαγητό, και αν φέρετε δική σας τούρτα, παρακαλούμε να ελέγξετε κι εσείς τα συστατικά. Για να κλείσει η κράτηση, χρειαζόμαστε μια προκαταβολή πενήντα ευρώ μέχρι την Παρασκευή.", "Not at all, as long as you tell us in advance. We'll prepare separate food, and if you bring your own cake, please check the ingredients yourselves too. To confirm the booking, we need a fifty-euro deposit by Friday."),
 ],
 "questions": [
  Q("Ποια ώρα είναι ελεύθερη το Σάββατο;", ["Το πρωί", "Το μεσημέρι", "Από τις πέντε ως τις οχτώ", "Όλη η μέρα"], 2, "από τις πέντε ως τις οχτώ"),
  Q("Τι περιλαμβάνει το βασικό πακέτο;", ["Δύο εμψυχωτές, παιχνίδια και ένα απλό μενού", "Μόνο την αίθουσα", "Την τούρτα και τα δώρα", "Φωτογράφο"], 0, "περιλαμβάνει δύο εμψυχωτές, παιχνίδια και ένα απλό μενού"),
  Q("Τι πρέπει να γίνει για να κλείσει η κράτηση;", ["Να υπογραφεί ένα συμβόλαιο", "Να δοθεί προκαταβολή πενήντα ευρώ μέχρι την Παρασκευή", "Να σταλεί η λίστα των παιδιών", "Να πληρωθεί όλο το ποσό"], 1, "χρειαζόμαστε μια προκαταβολή πενήντα ευρώ μέχρι την Παρασκευή"),
 ],
 "gloss": {"παιδότοπο": "παιδότοπος — children's play centre", "τρίωρο": "τρίωρο — three-hour slot", "πακέτο": "πακέτο — package", "εμψυχωτές": "εμψυχωτής — entertainer, activity leader", "τούρτα": "τούρτα — (birthday) cake", "ζαχαροπλαστείο": "ζαχαροπλαστείο — patisserie", "αλλεργία": "αλλεργία — allergy", "ξηρούς": "ξηροί καρποί — nuts", "συστατικά": "συστατικό — ingredient", "κράτηση": "κράτηση — booking", "προκαταβολή": "προκαταβολή — deposit"}
})
ITEMS.append({
 "id": "l101-int-typografos", "title": "Ένας τυπογράφος παλιάς σχολής", "title_en": "An old-school printer", "type": "interview", "level": "B2",
 "context_el": "Σε μια εκπομπή για τις παραδοσιακές τέχνες, μια δημοσιογράφος μιλά με έναν τυπογράφο που δουλεύει ακόμα με μεταλλικά στοιχεία.",
 "script": [
  L("Δημοσιογράφος", "f", "Κύριε Λάμπρου, σε μια εποχή εκτυπωτών και υπολογιστών, εσείς τυπώνετε ακόμα με το χέρι. Γιατί;", "Mr Lambrou, in an age of printers and computers, you still print by hand. Why?"),
  L("Τυπογράφος", "m", "Γιατί αυτό ξέρω να κάνω, και γιατί ο κόσμος το ξαναζητά. Στοιχειοθετώ κάθε λέξη με μικρά μεταλλικά γράμματα, ένα ένα, ανάποδα, και μετά τυπώνω στο πιεστήριο. Το χαρτί δέχεται μια ελαφριά πίεση, και τα γράμματα αφήνουν ένα αποτύπωμα που το νιώθεις με τα δάχτυλα. Αυτό ένας εκτυπωτής δεν μπορεί να το κάνει.", "Because that's what I know how to do, and because people are asking for it again. I set every word with small metal letters, one by one, backwards, and then I print on the press. The paper receives a light pressure, and the letters leave an impression that you can feel with your fingers. A printer can't do that."),
  L("Δημοσιογράφος", "f", "Ποιοι είναι οι πελάτες σας σήμερα;", "Who are your customers today?"),
  L("Τυπογράφος", "m", "Κυρίως ζευγάρια που θέλουν ξεχωριστά προσκλητήρια γάμου, μικροί εκδοτικοί οίκοι που βγάζουν ποιητικές συλλογές σε λίγα αντίτυπα, και γραφίστες. Παλιότερα τύπωνα τιμολόγια και αφίσες για το σινεμά της γειτονιάς. Σήμερα κάνω λιγότερα πράγματα, αλλά πιο προσεγμένα.", "Mainly couples who want special wedding invitations, small publishing houses that bring out poetry collections in a few copies, and graphic designers. In the past I printed invoices and posters for the neighbourhood cinema. Today I do fewer things, but more carefully made."),
  L("Δημοσιογράφος", "f", "Έχετε κάποιον να συνεχίσει τη δουλειά;", "Do you have someone to carry on the work?"),
  L("Τυπογράφος", "m", "Κάθε Σάββατο κάνω εργαστήρια για νέους, και δύο από αυτούς έρχονται πια τακτικά να βοηθήσουν. Δεν ξέρω αν θα το κάνουν επάγγελμα, αλλά τουλάχιστον τα στοιχεία δεν θα καταλήξουν σε μια αποθήκη.", "Every Saturday I run workshops for young people, and two of them now come regularly to help. I don't know if they'll make it their profession, but at least the type won't end up in a storeroom."),
 ],
 "questions": [
  Q("Τι ξεχωρίζει, κατά τον τυπογράφο, την εκτύπωση με το χέρι;", ["Είναι πιο γρήγορη", "Τα γράμματα αφήνουν ένα αποτύπωμα που το νιώθεις με τα δάχτυλα", "Είναι πιο φθηνή", "Χρησιμοποιεί περισσότερα χρώματα"], 1, "τα γράμματα αφήνουν ένα αποτύπωμα που το νιώθεις με τα δάχτυλα"),
  Q("Ποιοι είναι σήμερα κυρίως οι πελάτες του;", ["Τράπεζες και δημόσιες υπηρεσίες", "Κινηματογράφοι", "Ζευγάρια, μικροί εκδοτικοί οίκοι και γραφίστες", "Εφημερίδες"], 2, "Κυρίως ζευγάρια που θέλουν ξεχωριστά προσκλητήρια γάμου"),
  Q("Τι κάνει κάθε Σάββατο;", ["Εργαστήρια για νέους", "Πουλάει τα στοιχεία του", "Επισκέπτεται εκθέσεις", "Κλείνει το τυπογραφείο"], 0, "Κάθε Σάββατο κάνω εργαστήρια για νέους"),
 ],
 "gloss": {"τυπογράφο": "τυπογράφος — printer (person)", "στοιχεία": "στοιχείο — (printing) type, letter", "εκτυπωτών": "εκτυπωτής — (computer) printer", "πιεστήριο": "πιεστήριο — printing press", "αποτύπωμα": "αποτύπωμα — impression, imprint", "προσκλητήρια": "προσκλητήριο — invitation card", "εκδοτικοί": "εκδοτικός οίκος — publishing house", "αντίτυπα": "αντίτυπο — copy", "τιμολόγια": "τιμολόγιο — invoice", "προσεγμένα": "προσεγμένος — carefully made"}
})
ITEMS.append({
 "id": "l101-rep-psifiaka-kapi", "title": "Οι παππούδες μαθαίνουν τα κινητά", "title_en": "Grandparents learn to use smartphones", "type": "report", "level": "B2",
 "context_el": "Ακούτε ένα ρεπορτάζ σε μια ραδιοφωνική εκπομπή για ένα πρόγραμμα σε ένα Κέντρο Ανοιχτής Προστασίας Ηλικιωμένων (ΚΑΠΗ).",
 "script": [
  L("Ρεπόρτερ", "f", "Κάθε Τετάρτη απόγευμα, στο ΚΑΠΗ της γειτονιάς, δεκαπέντε ηλικιωμένοι κάθονται γύρω από ένα μεγάλο τραπέζι με τα κινητά τους στο χέρι. Απέναντί τους, μαθητές του διπλανού λυκείου τους εξηγούν υπομονετικά πώς να στέλνουν μηνύματα, να κάνουν βιντεοκλήσεις και να κλείνουν ραντεβού με τον γιατρό μέσω διαδικτύου.", "Every Wednesday afternoon, at the neighbourhood day centre for the elderly, fifteen older people sit round a large table with their mobiles in hand. Opposite them, pupils from the nearby high school patiently explain how to send messages, make video calls and book doctor's appointments online."),
  L("Ρεπόρτερ", "f", "Η ιδέα ξεκίνησε από μια καθηγήτρια πληροφορικής, που είδε τη γιαγιά της να δυσκολεύεται να συνδεθεί με την εφαρμογή της τράπεζας. Το πρόγραμμα έχει διπλό όφελος: οι ηλικιωμένοι γίνονται πιο αυτόνομοι, και οι μαθητές μαθαίνουν να εξηγούν απλά πράγματα που για εκείνους είναι αυτονόητα.", "The idea came from an IT teacher, who saw her grandmother struggling to log in to her bank's app. The programme has a double benefit: the elderly become more independent, and the pupils learn to explain simple things that are self-evident to them."),
  L("Ρεπόρτερ", "f", "Ιδιαίτερη έμφαση δίνεται στην ασφάλεια. Οι μαθητές δείχνουν στους ηλικιωμένους πώς να αναγνωρίζουν ύποπτα μηνύματα που ζητούν κωδικούς ή χρήματα, μια μορφή απάτης που, όπως λένε οι ίδιοι, έχει θύματα κυρίως ανάμεσα στους μεγαλύτερους. Στο τέλος κάθε μαθήματος, πάντως, η συζήτηση συνήθως ξεφεύγει από την τεχνολογία, και οι παππούδες διηγούνται στα παιδιά ιστορίες από τα δικά τους νιάτα.", "Particular emphasis is placed on security. The pupils show the elderly how to recognise suspicious messages asking for passwords or money, a form of fraud which, as they say, claims victims mainly among older people. At the end of each lesson, though, the conversation usually drifts away from technology, and the grandparents tell the young people stories from their own youth."),
 ],
 "questions": [
  Q("Ποιοι διδάσκουν τους ηλικιωμένους;", ["Υπάλληλοι μιας εταιρείας κινητής τηλεφωνίας", "Μαθητές του διπλανού λυκείου", "Εθελοντές του δήμου", "Τα εγγόνια τους"], 1, "μαθητές του διπλανού λυκείου τους εξηγούν υπομονετικά"),
  Q("Πώς ξεκίνησε η ιδέα;", ["Από μια καθηγήτρια που είδε τη γιαγιά της να δυσκολεύεται με την εφαρμογή της τράπεζας", "Από μια τράπεζα", "Από το υπουργείο", "Από έναν ηλικιωμένο που έχασε χρήματα"], 0, "είδε τη γιαγιά της να δυσκολεύεται να συνδεθεί με την εφαρμογή της τράπεζας"),
  Q("Τι μαθαίνουν σχετικά με την ασφάλεια;", ["Να μη χρησιμοποιούν ποτέ το ίντερνετ", "Να αλλάζουν κινητό κάθε χρόνο", "Να αναγνωρίζουν ύποπτα μηνύματα που ζητούν κωδικούς ή χρήματα", "Να κλείνουν το κινητό το βράδυ"], 2, "πώς να αναγνωρίζουν ύποπτα μηνύματα που ζητούν κωδικούς ή χρήματα"),
 ],
 "gloss": {"ηλικιωμένοι": "ηλικιωμένος — elderly person", "βιντεοκλήσεις": "βιντεοκλήση — video call", "πληροφορικής": "πληροφορική — computer science, IT", "δυσκολεύεται": "δυσκολεύομαι — to struggle", "όφελος": "όφελος — benefit", "αυτόνομοι": "αυτόνομος — independent", "αυτονόητα": "αυτονόητος — self-evident", "ύποπτα": "ύποπτος — suspicious", "απάτης": "απάτη — fraud, scam", "θύματα": "θύμα — victim", "νιάτα": "νιάτα — youth"}
})
ITEMS.append({
 "id": "l101-rep-farmakeftika-fyta", "title": "Ένας κήπος με φαρμακευτικά φυτά", "title_en": "A garden of medicinal plants", "type": "report", "level": "B2",
 "context_el": "Ακούτε ένα ρεπορτάζ σε μια εκπομπή για τη φύση σχετικά με έναν δημόσιο κήπο.",
 "script": [
  L("Ρεπόρτερ", "m", "Σε ένα οικόπεδο που για χρόνια ήταν εγκαταλειμμένο, στην άκρη της πόλης, μια ομάδα βοτανολόγων και εθελοντών δημιούργησε έναν κήπο με περισσότερα από διακόσια είδη αρωματικών και φαρμακευτικών φυτών της ελληνικής χλωρίδας. Ανάμεσά τους υπάρχουν γνωστά φυτά, όπως το φασκόμηλο, η ρίγανη και το δίκταμο της Κρήτης, αλλά και σπάνια είδη που απειλούνται με εξαφάνιση.", "On a plot that was abandoned for years, at the edge of the city, a group of botanists and volunteers created a garden with more than two hundred species of aromatic and medicinal plants of the Greek flora. Among them are well-known plants, such as sage, oregano and Cretan dittany, but also rare species threatened with extinction."),
  L("Ρεπόρτερ", "m", "Κάθε φυτό έχει μια πινακίδα με το όνομά του στα ελληνικά και στα λατινικά, καθώς και πληροφορίες για τις παραδοσιακές του χρήσεις. Οι υπεύθυνοι, ωστόσο, τονίζουν ότι ο κήπος δεν είναι φαρμακείο. «Πολλά φυτά έχουν πράγματι δραστικές ουσίες», εξηγεί μια βοτανολόγος. «Γι' αυτό ακριβώς δεν πρέπει να τα χρησιμοποιούμε χωρίς να συμβουλευτούμε γιατρό.»", "Each plant has a sign with its name in Greek and Latin, as well as information about its traditional uses. Those in charge, however, stress that the garden is not a pharmacy. 'Many plants do indeed have active substances,' explains a botanist. 'That is exactly why we shouldn't use them without consulting a doctor.'"),
  L("Ρεπόρτερ", "m", "Ο κήπος είναι ανοιχτός στο κοινό κάθε μέρα, εκτός από τη Δευτέρα, και η είσοδος είναι ελεύθερη. Τα σχολεία μπορούν να κλείσουν ξεναγήσεις, ενώ την άνοιξη οργανώνεται μια γιορτή, όπου οι επισκέπτες ανταλλάσσουν σπόρους και φυτά από τους δικούς τους κήπους.", "The garden is open to the public every day except Monday, and entry is free. Schools can book guided tours, while in spring a festival is organised where visitors exchange seeds and plants from their own gardens."),
 ],
 "questions": [
  Q("Τι υπήρχε πριν στη θέση του κήπου;", ["Ένα πάρκινγκ", "Ένα εγκαταλειμμένο οικόπεδο", "Ένα παλιό σχολείο", "Ένα εργοστάσιο"], 1, "Σε ένα οικόπεδο που για χρόνια ήταν εγκαταλειμμένο"),
  Q("Γιατί, κατά τη βοτανολόγο, δεν πρέπει να χρησιμοποιούμε τα φυτά χωρίς γιατρό;", ["Γιατί είναι ακριβά", "Γιατί είναι σπάνια", "Γιατί πολλά έχουν δραστικές ουσίες", "Γιατί απαγορεύεται από τον νόμο"], 2, "Πολλά φυτά έχουν πράγματι δραστικές ουσίες"),
  Q("Τι γίνεται στη γιορτή της άνοιξης;", ["Οι επισκέπτες ανταλλάσσουν σπόρους και φυτά", "Πουλιούνται φάρμακα", "Γίνονται συναυλίες", "Φυτεύονται δέντρα στους δρόμους"], 0, "οι επισκέπτες ανταλλάσσουν σπόρους και φυτά"),
 ],
 "gloss": {"οικόπεδο": "οικόπεδο — plot of land", "βοτανολόγων": "βοτανολόγος — botanist", "αρωματικών": "αρωματικός — aromatic", "φαρμακευτικών": "φαρμακευτικός — medicinal", "χλωρίδας": "χλωρίδα — flora", "φασκόμηλο": "φασκόμηλο — sage", "δίκταμο": "δίκταμο — dittany", "εξαφάνιση": "εξαφάνιση — extinction", "δραστικές": "δραστικός — active, potent", "ουσίες": "ουσία — substance", "ανταλλάσσουν": "ανταλλάσσω — to exchange", "σπόρους": "σπόρος — seed"}
})
ITEMS.append({
 "id": "l101-mono-cheimonas-sto-nisi", "title": "Ένας χειμώνας στο νησί", "title_en": "A winter on the island", "type": "monologue", "level": "B2",
 "context_el": "Ένας νεαρός άντρας μιλά σε φίλους για τον χειμώνα που πέρασε σε ένα μικρό νησί.",
 "script": [
  L("Φώτης", "m", "Πέρσι δούλευα το καλοκαίρι σε ένα ξενοδοχείο στη Σίφνο, και τον Οκτώβριο αποφάσισα να μη γυρίσω στην Αθήνα. Ήθελα να δω πώς είναι το νησί όταν φεύγουν οι τουρίστες. Έτσι νοίκιασα ένα μικρό σπίτι στο χωριό με πολύ χαμηλό ενοίκιο, γιατί τον χειμώνα τα περισσότερα μένουν άδεια.", "Last year I worked in the summer at a hotel on Sifnos, and in October I decided not to go back to Athens. I wanted to see what the island is like when the tourists leave. I rented a small house in the village at a very low rent, because in winter most of them stay empty."),
  L("Φώτης", "m", "Οι πρώτες εβδομάδες ήταν δύσκολες. Τα περισσότερα μαγαζιά έκλεισαν, το πλοίο ερχόταν πιο αραιά, και όταν φυσούσε δυνατά δεν ερχόταν καθόλου. Ένιωθα λίγο αποκομμένος. Σιγά σιγά, όμως, γνώρισα τους ανθρώπους που ζουν εκεί όλο τον χρόνο. Ο γείτονάς μου, ένας ηλικιωμένος ψαράς, μου έμαθε να μαντάρω δίχτυα, και τα βράδια μαζευόμασταν στο μοναδικό ανοιχτό καφενείο.", "The first weeks were difficult. Most shops closed, the boat came less often, and when it was very windy it didn't come at all. I felt a bit cut off. Little by little, though, I got to know the people who live there all year round. My neighbour, an old fisherman, taught me to mend nets, and in the evenings we gathered at the only open café."),
  L("Φώτης", "m", "Τον Μάρτιο γύρισα στην Αθήνα, αλλά κάτι είχε αλλάξει μέσα μου. Έμαθα να βαριέμαι χωρίς να πανικοβάλλομαι, να περπατάω ώρες χωρίς προορισμό. Και κατάλαβα ότι ένα νησί δεν είναι μόνο παραλίες και ταβέρνες· είναι μια μικρή κοινωνία που παλεύει να κρατηθεί ζωντανή όταν δεν την κοιτάζει κανείς.", "In March I went back to Athens, but something had changed inside me. I learned to be bored without panicking, to walk for hours with no destination. And I realised that an island isn't just beaches and tavernas; it's a small society that struggles to stay alive when no one is looking at it."),
 ],
 "questions": [
  Q("Γιατί έμεινε στο νησί τον χειμώνα;", ["Γιατί βρήκε δουλειά σε ένα σχολείο", "Γιατί ήθελε να δει πώς είναι το νησί όταν φεύγουν οι τουρίστες", "Γιατί δεν είχε εισιτήριο", "Γιατί αρρώστησε"], 1, "Ήθελα να δω πώς είναι το νησί όταν φεύγουν οι τουρίστες"),
  Q("Τι του έμαθε ο γείτονάς του;", ["Να ψαρεύει με καλάμι", "Να μαγειρεύει ψάρι", "Να μαντάρει δίχτυα", "Να οδηγεί βάρκα"], 2, "μου έμαθε να μαντάρω δίχτυα"),
  Q("Τι κατάλαβε στο τέλος;", ["Ότι ένα νησί είναι μια μικρή κοινωνία που παλεύει να μείνει ζωντανή", "Ότι προτιμά την Αθήνα", "Ότι δεν μπορεί να ζήσει χωρίς τουρίστες", "Ότι ο χειμώνας στα νησιά είναι βαρετός"], 0, "είναι μια μικρή κοινωνία που παλεύει να κρατηθεί ζωντανή"),
 ],
 "gloss": {"νοίκιασα": "νοικιάζω — to rent", "ενοίκιο": "ενοίκιο — rent", "αραιά": "αραιά — rarely, at long intervals", "αποκομμένος": "αποκομμένος — cut off", "μαντάρω": "μαντάρω — to mend, darn", "δίχτυα": "δίχτυ — (fishing) net", "βαριέμαι": "βαριέμαι — to be bored", "πανικοβάλλομαι": "πανικοβάλλομαι — to panic", "προορισμό": "προορισμός — destination", "παλεύει": "παλεύω — to struggle"}
})
ITEMS.append({
 "id": "l101-mono-mikrotero-spiti", "title": "Γιατί μετακόμισα σε μικρότερο σπίτι", "title_en": "Why I moved to a smaller home", "type": "monologue", "level": "B2",
 "context_el": "Μια γυναίκα μιλά σε ένα podcast για την απόφασή της να μετακομίσει σε ένα μικρότερο διαμέρισμα.",
 "script": [
  L("Δέσποινα", "f", "Όταν τα παιδιά μου έφυγαν για σπουδές, έμεινα μόνη σε ένα διαμέρισμα εκατόν είκοσι τετραγωνικών. Τα δύο δωμάτια ήταν κλειστά τον περισσότερο καιρό, αλλά τα πλήρωνα: θέρμανση, κοινόχρηστα, καθάρισμα. Κάποια μέρα κάθισα και υπολόγισα πόσα ξόδευα για χώρους που δεν χρησιμοποιούσα, και τρόμαξα.", "When my children left to study, I was left alone in a hundred-and-twenty-square-metre flat. The two bedrooms were closed most of the time, but I paid for them: heating, building charges, cleaning. One day I sat down and calculated how much I was spending on spaces I didn't use, and I was shocked."),
  L("Δέσποινα", "f", "Το πιο δύσκολο δεν ήταν να βρω καινούργιο σπίτι, αλλά να αποφασίσω τι θα κρατήσω. Είχα μαζέψει πράγματα τριάντα χρόνων. Έδωσα ρούχα και έπιπλα σε έναν φιλανθρωπικό σύλλογο, πούλησα βιβλία σε ένα παλαιοβιβλιοπωλείο και κράτησα μόνο ό,τι χρησιμοποιούσα πραγματικά ή ό,τι είχε μεγάλη συναισθηματική αξία.", "The hardest thing wasn't finding a new home, but deciding what to keep. I had collected thirty years' worth of things. I gave clothes and furniture to a charity, sold books to a second-hand bookshop and kept only what I really used or what had great sentimental value."),
  L("Δέσποινα", "f", "Σήμερα μένω σε ένα διαμέρισμα πενήντα πέντε τετραγωνικών, πιο κοντά στο κέντρο, και πηγαίνω παντού με τα πόδια. Τα παιδιά, όταν έρχονται, κοιμούνται στον καναπέ-κρεβάτι και γκρινιάζουν λίγο, αλλά εγώ νιώθω πιο ελαφριά. Όπως λέω στις φίλες μου, δεν έχασα χώρο· κέρδισα χρόνο.", "Today I live in a fifty-five-square-metre flat, closer to the centre, and I walk everywhere. When the children come, they sleep on the sofa bed and grumble a little, but I feel lighter. As I tell my friends, I didn't lose space; I gained time."),
 ],
 "questions": [
  Q("Τι την έκανε να σκεφτεί τη μετακόμιση;", ["Ένα πρόβλημα με τους γείτονες", "Υπολόγισε πόσα ξόδευε για χώρους που δεν χρησιμοποιούσε", "Της το πρότειναν τα παιδιά της", "Πουλήθηκε η πολυκατοικία"], 1, "υπολόγισα πόσα ξόδευα για χώρους που δεν χρησιμοποιούσα"),
  Q("Ποιο ήταν, για εκείνη, το πιο δύσκολο;", ["Να αποφασίσει τι θα κρατήσει", "Να βρει καινούργιο σπίτι", "Να συνηθίσει τη νέα γειτονιά", "Να πουλήσει το παλιό σπίτι"], 0, "να αποφασίσω τι θα κρατήσω"),
  Q("Τι λέει στις φίλες της;", ["Ότι μετάνιωσε", "Ότι θέλει να ξαναμετακομίσει", "Ότι δεν έχασε χώρο, αλλά κέρδισε χρόνο", "Ότι τα παιδιά δεν την επισκέπτονται πια"], 2, "δεν έχασα χώρο· κέρδισα χρόνο"),
 ],
 "gloss": {"τετραγωνικών": "τετραγωνικό — square metre", "θέρμανση": "θέρμανση — heating", "κοινόχρηστα": "κοινόχρηστα — shared building charges", "υπολόγισα": "υπολογίζω — to calculate", "τρόμαξα": "τρομάζω — to be shocked, frightened", "φιλανθρωπικό": "φιλανθρωπικός — charitable", "παλαιοβιβλιοπωλείο": "παλαιοβιβλιοπωλείο — second-hand bookshop", "συναισθηματική": "συναισθηματικός — sentimental", "γκρινιάζουν": "γκρινιάζω — to grumble", "ελαφριά": "ελαφρύς — light"}
})
ITEMS.append({
 "id": "l101-c1-synaisthimata-zoon", "title": "Νιώθουν τα ζώα συναισθήματα;", "title_en": "Do animals have emotions?", "type": "monologue", "level": "C1",
 "context_el": "Ακούτε απόσπασμα από μια διάλεξη για τη συμπεριφορά των ζώων σε ένα πανεπιστήμιο, ανοιχτή στο κοινό.",
 "script": [
  L("Ομιλήτρια", "f", "Όποιος έχει σκύλο δεν χρειάζεται να πειστεί ότι το ζώο του χαίρεται όταν τον βλέπει. Για μεγάλο μέρος του εικοστού αιώνα, όμως, η επιστήμη αντιμετώπιζε τέτοιες δηλώσεις με καχυποψία. Το να αποδίδουμε συναισθήματα στα ζώα θεωρούνταν ανθρωπομορφισμός, δηλαδή προβολή των δικών μας εμπειριών σε όντα που, απ' ό,τι υποστήριζαν πολλοί, απλώς αντιδρούν σε ερεθίσματα.", "Anyone who has a dog doesn't need to be convinced that their animal is happy when it sees them. For much of the twentieth century, however, science treated such claims with suspicion. Attributing emotions to animals was considered anthropomorphism, that is, projecting our own experiences onto beings that, as many argued, simply react to stimuli."),
  L("Ομιλήτρια", "f", "Τις τελευταίες δεκαετίες η εικόνα έχει αλλάξει σημαντικά. Ο νευροεπιστήμονας Γιακ Πάνκσεπ έδειξε ότι οι αρουραίοι, όταν τους γαργαλάνε, βγάζουν υπερήχους που μοιάζουν με γέλιο και επιδιώκουν να ξαναζήσουν την εμπειρία. Σε ένα γνωστό πείραμα με καπουτσίνους πιθήκους, όταν ένας πίθηκος έπαιρνε αγγούρι για μια δουλειά για την οποία ο διπλανός του έπαιρνε σταφύλι, συχνά πετούσε το αγγούρι με εμφανή αγανάκτηση.", "In recent decades the picture has changed significantly. The neuroscientist Jaak Panksepp showed that rats, when tickled, emit ultrasounds resembling laughter and seek to relive the experience. In a well-known experiment with capuchin monkeys, when one monkey received cucumber for a task for which its neighbour received a grape, it often threw the cucumber away with evident indignation."),
  L("Ομιλήτρια", "f", "Το 2012, μια ομάδα επιστημόνων υπέγραψε στο Κέιμπριτζ μια διακήρυξη σύμφωνα με την οποία τα θηλαστικά, τα πουλιά και ορισμένα άλλα ζώα διαθέτουν τα νευρολογικά υποστρώματα που απαιτούνται για τη συνείδηση. Αυτό δεν σημαίνει ότι ένας σκύλος νιώθει ακριβώς ό,τι κι εμείς· σημαίνει ότι η απόλυτη διάκριση ανάμεσα στον άνθρωπο και στα άλλα ζώα δεν στέκει πια.", "In 2012, a group of scientists signed a declaration in Cambridge according to which mammals, birds and some other animals possess the neurological substrates required for consciousness. This doesn't mean a dog feels exactly what we feel; it means that the absolute distinction between humans and other animals no longer holds."),
  L("Ομιλήτρια", "f", "Το πραγματικό δίλημμα, λοιπόν, δεν είναι πια αν τα ζώα έχουν συναισθήματα, αλλά τι σημαίνει αυτό για τον τρόπο που τα εκτρέφουμε, τα χρησιμοποιούμε σε πειράματα ή τα κρατάμε σε αιχμαλωσία. Και αυτό είναι ερώτημα που η επιστήμη μπορεί να φωτίσει, αλλά δεν μπορεί να απαντήσει μόνη της.", "The real dilemma, then, is no longer whether animals have emotions, but what this means for the way we farm them, use them in experiments or keep them in captivity. And that is a question science can shed light on, but cannot answer on its own."),
 ],
 "questions": [
  Q("Πώς θεωρούνταν για μεγάλο μέρος του 20ού αιώνα η απόδοση συναισθημάτων στα ζώα;", ["Ως αποδεδειγμένο επιστημονικό γεγονός", "Ως ανθρωπομορφισμός", "Ως θέμα μόνο για φιλοσόφους", "Ως κάτι που ισχύει μόνο για τους σκύλους"], 1, "θεωρούνταν ανθρωπομορφισμός"),
  Q("Τι έδειξε ο Γιακ Πάνκσεπ;", ["Ότι οι αρουραίοι βγάζουν υπερήχους που μοιάζουν με γέλιο όταν τους γαργαλάνε", "Ότι οι αρουραίοι δεν νιώθουν πόνο", "Ότι οι πίθηκοι προτιμούν το αγγούρι", "Ότι οι σκύλοι αναγνωρίζουν πρόσωπα"], 0, "βγάζουν υπερήχους που μοιάζουν με γέλιο"),
  Q("Τι υποστηρίζει η διακήρυξη του 2012;", ["Ότι τα ζώα νιώθουν ακριβώς ό,τι κι εμείς", "Ότι μόνο ο άνθρωπος έχει συνείδηση", "Ότι πολλά ζώα διαθέτουν τα νευρολογικά υποστρώματα που απαιτούνται για τη συνείδηση", "Ότι πρέπει να σταματήσουν όλα τα πειράματα"], 2, "διαθέτουν τα νευρολογικά υποστρώματα που απαιτούνται για τη συνείδηση"),
  Q("Ποιο είναι, κατά την ομιλήτρια, το πραγματικό δίλημμα σήμερα;", ["Αν τα ζώα έχουν συναισθήματα", "Τι σημαίνει αυτό για τον τρόπο που μεταχειριζόμαστε τα ζώα", "Πώς να μετρήσουμε τη νοημοσύνη των ζώων", "Αν οι πίθηκοι μπορούν να μιλήσουν"], 1, "τι σημαίνει αυτό για τον τρόπο που τα εκτρέφουμε"),
 ],
 "gloss": {"καχυποψία": "καχυποψία — suspicion", "αποδίδουμε": "αποδίδω — to attribute", "ανθρωπομορφισμός": "ανθρωπομορφισμός — anthropomorphism", "προβολή": "προβολή — projection", "ερεθίσματα": "ερέθισμα — stimulus", "αρουραίοι": "αρουραίος — rat", "γαργαλάνε": "γαργαλάω — to tickle", "υπερήχους": "υπέρηχος — ultrasound", "αγανάκτηση": "αγανάκτηση — indignation", "διακήρυξη": "διακήρυξη — declaration", "υποστρώματα": "υπόστρωμα — substrate", "συνείδηση": "συνείδηση — consciousness", "εκτρέφουμε": "εκτρέφω — to farm, rear", "αιχμαλωσία": "αιχμαλωσία — captivity"}
})
ITEMS.append({
 "id": "l101-c1-proti-entyposi", "title": "Πόσο αξίζει η πρώτη εντύπωση;", "title_en": "How much is a first impression worth?", "type": "interview", "level": "C1",
 "context_el": "Σε μια εκπομπή για την ψυχολογία, ένας δημοσιογράφος συζητά με μια κοινωνική ψυχολόγο για τις πρώτες εντυπώσεις.",
 "script": [
  L("Δημοσιογράφος", "m", "Λέμε συχνά ότι δεν έχεις δεύτερη ευκαιρία να κάνεις καλή πρώτη εντύπωση. Πόσο γρήγορα, αλήθεια, σχηματίζουμε γνώμη για κάποιον;", "We often say you don't get a second chance to make a good first impression. How quickly, really, do we form an opinion about someone?"),
  L("Ψυχολόγος", "f", "Εντυπωσιακά γρήγορα. Σε πειράματα του Πανεπιστημίου του Πρίνστον, οι συμμετέχοντες έβλεπαν φωτογραφίες προσώπων για μόλις ένα δέκατο του δευτερολέπτου. Οι κρίσεις τους για το αν ένα πρόσωπο φαινόταν αξιόπιστο ή ικανό διέφεραν ελάχιστα από εκείνες που έκαναν όταν είχαν όσο χρόνο ήθελαν. Με άλλα λόγια, ο επιπλέον χρόνος απλώς επιβεβαίωνε την αρχική εντύπωση.", "Impressively quickly. In experiments at Princeton University, participants saw photographs of faces for just a tenth of a second. Their judgements about whether a face seemed trustworthy or competent differed very little from those they made when they had as much time as they wanted. In other words, the extra time simply confirmed the initial impression."),
  L("Δημοσιογράφος", "m", "Και είναι σωστές αυτές οι κρίσεις;", "And are these judgements correct?"),
  L("Ψυχολόγος", "f", "Εδώ είναι το ενδιαφέρον. Είμαστε πολύ σίγουροι γι' αυτές, αλλά η ακρίβειά τους, όταν βασίζονται μόνο σε ένα πρόσωπο, είναι συνήθως μέτρια, αν όχι κακή. Ένα πρόσωπο που μας φαίνεται «τίμιο» δεν ανήκει απαραίτητα σε έναν τίμιο άνθρωπο. Τα πράγματα είναι κάπως καλύτερα όταν βλέπουμε τον άλλον να κινείται και να μιλά, έστω και για λίγα δευτερόλεπτα· τότε μπορούμε να εκτιμήσουμε σχετικά καλά, για παράδειγμα, πόσο εξωστρεφής είναι.", "This is where it gets interesting. We are very sure of them, but their accuracy, when they are based only on a face, is usually mediocre, if not poor. A face that seems 'honest' to us doesn't necessarily belong to an honest person. Things are somewhat better when we see the other person moving and speaking, even for a few seconds; then we can judge fairly well, for example, how extroverted they are."),
  L("Δημοσιογράφος", "m", "Τι σημαίνει αυτό στην πράξη, για παράδειγμα σε μια συνέντευξη για δουλειά;", "What does that mean in practice, for example in a job interview?"),
  L("Ψυχολόγος", "f", "Ότι όσοι παίρνουν αποφάσεις πρέπει να προστατεύονται από τον εαυτό τους. Οι δομημένες συνεντεύξεις, όπου όλοι οι υποψήφιοι απαντούν στις ίδιες ερωτήσεις και αξιολογούνται με τα ίδια κριτήρια, προβλέπουν πολύ καλύτερα την απόδοση από μια ελεύθερη κουβέντα, στην οποία η πρώτη εντύπωση κυριαρχεί χωρίς να το καταλαβαίνουμε.", "That decision-makers need to be protected from themselves. Structured interviews, where all candidates answer the same questions and are assessed with the same criteria, predict performance much better than a free conversation, in which the first impression dominates without us realising it."),
 ],
 "questions": [
  Q("Τι έδειξαν τα πειράματα του Πρίνστον;", ["Ότι χρειαζόμαστε αρκετά λεπτά για να κρίνουμε ένα πρόσωπο", "Ότι οι κρίσεις μετά από ένα δέκατο του δευτερολέπτου διέφεραν ελάχιστα από εκείνες χωρίς χρονικό όριο", "Ότι οι συμμετέχοντες δεν μπορούσαν να κρίνουν τίποτα", "Ότι οι φωτογραφίες ήταν παραπλανητικές"], 1, "διέφεραν ελάχιστα από εκείνες που έκαναν όταν είχαν όσο χρόνο ήθελαν"),
  Q("Πόσο ακριβείς είναι οι κρίσεις που βασίζονται μόνο σε ένα πρόσωπο;", ["Πολύ ακριβείς", "Πάντα λανθασμένες", "Συνήθως μέτριες, αν όχι κακές", "Ακριβείς μόνο για τους άντρες"], 2, "είναι συνήθως μέτρια, αν όχι κακή"),
  Q("Πότε οι κρίσεις μας γίνονται κάπως καλύτερες;", ["Όταν βλέπουμε τον άλλον να κινείται και να μιλά", "Όταν βλέπουμε περισσότερες φωτογραφίες", "Όταν είμαστε κουρασμένοι", "Όταν ο άλλος χαμογελά"], 0, "όταν βλέπουμε τον άλλον να κινείται και να μιλά"),
  Q("Τι προτείνει η ψυχολόγος για τις συνεντεύξεις εργασίας;", ["Να γίνονται μόνο με βίντεο", "Να διαρκούν περισσότερο", "Να κρίνει πάντα ένα μόνο άτομο", "Να είναι δομημένες, με τις ίδιες ερωτήσεις και τα ίδια κριτήρια για όλους"], 3, "Οι δομημένες συνεντεύξεις, όπου όλοι οι υποψήφιοι απαντούν στις ίδιες ερωτήσεις"),
 ],
 "gloss": {"σχηματίζουμε": "σχηματίζω — to form", "αξιόπιστο": "αξιόπιστος — trustworthy", "ικανό": "ικανός — competent", "επιβεβαίωνε": "επιβεβαιώνω — to confirm", "ακρίβειά": "ακρίβεια — accuracy", "τίμιο": "τίμιος — honest", "εξωστρεφής": "εξωστρεφής — extroverted", "δομημένες": "δομημένος — structured", "υποψήφιοι": "υποψήφιος — candidate", "αξιολογούνται": "αξιολογούμαι — to be assessed", "κριτήρια": "κριτήριο — criterion", "απόδοση": "απόδοση — performance", "κυριαρχεί": "κυριαρχώ — to dominate"}
})

rnd = random.Random(101)  # spread the right answers over the four positions (the page shows options in file order)
for it in ITEMS:
    for q in it["questions"]: rnd.shuffle(q["options"])
for it in ITEMS:
    for q in it["questions"]: assert q["answer"] in q["options"], (it["id"], q["q"])
    for k in it["gloss"]:
        if not (any(k in s["el"] for s in it["script"]) or k in it["context_el"]): raise SystemExit(f"gloss key not in text: {it['id']} {k}")
root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
with open(os.path.join(root, "library", "listening", "listening-101.json"), "w", encoding="utf-8") as fh:
    json.dump({"items": ITEMS}, fh, ensure_ascii=False, indent=1); fh.write("\n")
print(len(ITEMS), "items,", sum(len(i["questions"]) for i in ITEMS), "questions")
